<?php
require_once __DIR__.'/layout.php'; $u=require_login(); $pdo=db();
if($u['role']==='teacher'){$st=$pdo->prepare("SELECT DISTINCT se.id,CONCAT(se.grade_name,' ',se.section_name,' · ',ay.name) label FROM teacher_assignments ta JOIN sections se ON se.id=ta.section_id JOIN academic_years ay ON ay.id=se.academic_year_id WHERE ta.user_id=? ORDER BY ay.active DESC,se.grade_name,se.section_name");$st->execute([$u['id']]);$sections=$st->fetchAll();}else{$sections=$pdo->query("SELECT se.id,CONCAT(se.grade_name,' ',se.section_name,' · ',ay.name) label FROM sections se JOIN academic_years ay ON ay.id=se.academic_year_id ORDER BY ay.active DESC,se.grade_name,se.section_name")->fetchAll();}
$sectionId=(int)($_GET['section_id']??$_POST['section_id']??0);$period=$_GET['period']??$_POST['period']??'P1';if(!in_array($period,['P1','P2','P3','P4'],true))$period='P1';
$allowedSection=true;if($u['role']==='teacher'&&$sectionId){$st=$pdo->prepare('SELECT COUNT(*) FROM teacher_assignments WHERE user_id=? AND section_id=?');$st->execute([$u['id'],$sectionId]);$allowedSection=(bool)$st->fetchColumn();}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save'){verify_csrf();if(!$allowedSection){http_response_code(403);exit('No autorizado');}$up=$pdo->prepare("INSERT INTO attendance(student_id,period,present,absent,updated_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE present=VALUES(present),absent=VALUES(absent),updated_by=VALUES(updated_by),updated_at=CURRENT_TIMESTAMP");foreach($_POST['student_ids']??[] as $sid){$sid=(int)$sid;$pre=$_POST['present'][$sid]??'';$abs=$_POST['absent'][$sid]??'';$up->execute([$sid,$period,$pre===''?null:(int)$pre,$abs===''?null:(int)$abs,$u['id']]);}flash('success','Asistencia guardada.');header('Location: attendance.php?section_id='.$sectionId.'&period='.$period);exit;}
$students=[];$existing=[];if($sectionId&&$allowedSection){$st=$pdo->prepare('SELECT id,order_no,names,last_names FROM students WHERE section_id=? AND active=1 ORDER BY order_no,last_names');$st->execute([$sectionId]);$students=$st->fetchAll();$st=$pdo->prepare('SELECT a.* FROM attendance a JOIN students st ON st.id=a.student_id WHERE st.section_id=? AND a.period=?');$st->execute([$sectionId,$period]);foreach($st as $a)$existing[$a['student_id']]=$a;}
app_header('Asistencia'); ?>
<div class="panel no-print"><form method="get" class="filters"><label>Grado / sección<select name="section_id" onchange="this.form.submit()"><option value="">Seleccione</option><?php foreach($sections as $s):?><option value="<?=$s['id']?>" <?=$sectionId==$s['id']?'selected':''?>><?=h($s['label'])?></option><?php endforeach;?></select></label><label>Período<select name="period" onchange="this.form.submit()"><?php foreach(['P1','P2','P3','P4'] as $p):?><option <?=$period===$p?'selected':''?>><?=$p?></option><?php endforeach;?></select></label></form></div>
<?php if($students):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="section_id" value="<?=$sectionId?>"><input type="hidden" name="period" value="<?=h($period)?>"><div class="panel"><h2>Asistencia · <?=h($period)?></h2><div class="table-wrap"><table class="sys-table"><thead><tr><th>No.</th><th>Estudiante</th><th>Asistencia</th><th>Ausencia</th></tr></thead><tbody><?php foreach($students as $s):$a=$existing[$s['id']]??[];?><tr><td><?=h($s['order_no'])?><input type="hidden" name="student_ids[]" value="<?=$s['id']?>"></td><td><b><?=h($s['last_names'].', '.$s['names'])?></b></td><td><input type="number" min="0" name="present[<?=$s['id']?>]" value="<?=h($a['present']??'')?>"></td><td><input type="number" min="0" name="absent[<?=$s['id']?>]" value="<?=h($a['absent']??'')?>"></td></tr><?php endforeach;?></tbody></table></div><div class="actions"><button class="button">Guardar asistencia</button></div></div></form><?php else:?><div class="panel empty">Seleccione una sección con estudiantes.</div><?php endif;?>
<?php app_footer(); ?>
